import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DOCUMENT_TYPES = ['구매품의', '검수조서', '대금지급', '실사계획', '자산변동'];
const APPROVAL_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

@Controller('api/v1')
export class FnSfr02507Controller {
  @Post('/asset-approvals')
  @HttpCode(200)
  async submitAssetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const documentType = data['documentType'];
    if (typeof documentType !== 'string' || !DOCUMENT_TYPES.includes(documentType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 유형을 선택해 주세요.');
    }
    const documentId = Number(data['documentId']);
    if (!Number.isInteger(documentId) || documentId <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID를 올바르게 입력해 주세요.');
    }
    // 검수조서·대금지급은 대응 테이블이 없어 구현하지 못했다 (todos 참고)
    if (documentType === '검수조서' || documentType === '대금지급') {
      throw new ApiError(400, 'VALIDATION_FAILED', '아직 상신할 수 없는 문서 유형입니다.');
    }
    return transaction(async (db) => {
      let found: any[] = [];
      if (documentType === '구매품의') {
        found = await db.query(
          'SELECT t.approval_document_id AS "approvalDocumentId", d.approval_status AS "status" FROM purchase_request t LEFT JOIN approval_document d ON d.approval_document_id = t.approval_document_id WHERE t.purchase_request_id = CAST(:id AS bigint) FOR UPDATE OF t',
          { id: documentId },
        );
      } else if (documentType === '실사계획') {
        found = await db.query(
          'SELECT t.approval_document_id AS "approvalDocumentId", d.approval_status AS "status" FROM asset_inspection_plan t LEFT JOIN approval_document d ON d.approval_document_id = t.approval_document_id WHERE t.asset_inspection_plan_id = CAST(:id AS bigint) FOR UPDATE OF t',
          { id: documentId },
        );
      } else {
        found = await db.query(
          'SELECT t.approval_document_id AS "approvalDocumentId", d.approval_status AS "status" FROM asset_change t LEFT JOIN approval_document d ON d.approval_document_id = t.approval_document_id WHERE t.asset_change_id = CAST(:id AS bigint) FOR UPDATE OF t',
          { id: documentId },
        );
      }
      if (found.length === 0) {
        throw new ApiError(404, 'ASSET_DOCUMENT_NOT_FOUND', '상신할 자산 업무 문서를 찾을 수 없습니다.');
      }
      const current = found[0].status;
      if (current === '결재대기' || current === '진행중') {
        throw new ApiError(409, 'ASSET_DOCUMENT_IN_APPROVAL', '이미 결재 중인 문서입니다.');
      }
      // 가정: 결재양식은 사용 중인 연계 결재 양식 중 첫 번째를 쓴다
      const forms = await db.query(
        "SELECT approval_form_id AS \"approvalFormId\" FROM approval_form WHERE is_linked_approval = true AND use_status = '사용' ORDER BY approval_form_id LIMIT 1",
        {},
      );
      const depts = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (forms.length === 0 || depts.length === 0 || depts[0].departmentId === null) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 연계에 실패했습니다. 결재양식 또는 기안부서를 확인해 주세요.');
      }
      // 가정: 문서번호는 'AST-' + 상신 시각 + 문서 ID로 만든다
      const created = await db.query(
        "INSERT INTO approval_document (approval_form_id, drafter_id, drafter_department_id, document_number, title, approval_status, is_urgent, is_secret, linked_business_type, linked_business_id, submitted_at, created_at, updated_at) VALUES (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:deptId AS bigint), CONCAT('AST-', to_char(now(), 'YYYYMMDDHH24MISSUS'), '-', CAST(:documentId AS text)), :title, '결재대기', false, false, :documentType, CAST(:documentId AS bigint), now(), now(), now()) RETURNING approval_document_id AS \"approvalDocumentId\", approval_status AS \"approvalStatus\"",
        {
          formId: forms[0].approvalFormId,
          userId: user.id,
          deptId: depts[0].departmentId,
          documentId,
          title: documentType + ' 결재 상신',
          documentType,
        },
      );
      const approvalDocumentId = created[0].approvalDocumentId;
      if (documentType === '구매품의') {
        await db.execute(
          "UPDATE purchase_request SET approval_document_id = CAST(:docId AS bigint), approval_status = '결재대기', updated_at = now() WHERE purchase_request_id = CAST(:id AS bigint)",
          { docId: approvalDocumentId, id: documentId },
        );
      } else if (documentType === '실사계획') {
        await db.execute(
          'UPDATE asset_inspection_plan SET approval_document_id = CAST(:docId AS bigint), updated_at = now() WHERE asset_inspection_plan_id = CAST(:id AS bigint)',
          { docId: approvalDocumentId, id: documentId },
        );
      } else {
        await db.execute(
          "UPDATE asset_change SET approval_document_id = CAST(:docId AS bigint), change_status = '결재대기', updated_at = now() WHERE asset_change_id = CAST(:id AS bigint)",
          { docId: approvalDocumentId, id: documentId },
        );
      }
      return { approvalDocumentId, approvalStatus: created[0].approvalStatus };
    });
  }

  @Get('/asset-approvals/:approvalDocumentId')
  async getAssetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const id = Number(req.params['approvalDocumentId']);
    if (!Number.isInteger(id) || id <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus", completed_at AS "completedAt" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재 문서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Post('/asset-approvals/result')
  @HttpCode(200)
  async receiveAssetApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    const data = checks.inputOf(req.body);
    const id = Number(data['approvalDocumentId']);
    if (!Number.isInteger(id) || id <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID를 올바르게 입력해 주세요.');
    }
    const status = data['approvalStatus'];
    if (typeof status !== 'string' || status === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 상태를 입력해 주세요.');
    }
    if (!APPROVAL_STATUSES.includes(status)) {
      throw new ApiError(422, 'INVALID_APPROVAL_STATUS', '허용되지 않는 결재 상태 값입니다.');
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT drafter_id AS "drafterId", linked_business_type AS "businessType" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재 문서를 찾을 수 없습니다.');
      }
      // 가정: 승인·반려·완료 시점에 완료 일시를 기록한다
      await db.execute(
        "UPDATE approval_document SET approval_status = :status, completed_at = CASE WHEN :status IN ('승인', '반려', '완료') THEN now() ELSE completed_at END, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)",
        { status, id },
      );
      const businessType = docs[0].businessType;
      let businessStatus: string = status;
      if (businessType === '구매품의') {
        await db.execute(
          'UPDATE purchase_request SET approval_status = :status, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)',
          { status, id },
        );
      } else if (businessType === '자산변동') {
        await db.execute(
          'UPDATE asset_change SET change_status = :status, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)',
          { status, id },
        );
      } else if (businessType === '실사계획') {
        // 가정: 실사계획은 승인·완료면 승인, 그 밖에는 신청으로 둔다
        businessStatus = status === '승인' || status === '완료' ? '승인' : '신청';
        await db.execute(
          'UPDATE asset_inspection_plan SET approval_status = :planStatus, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)',
          { planStatus: businessStatus, id },
        );
      }
      await db.execute(
        "INSERT INTO notification (employee_id, notification_type, event_type, title, summary, target_type, target_id, read_yn, occurred_at, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), 'ALERT', '자산결재결과', :title, :summary, 'ASSET_APPROVAL', CAST(:id AS bigint), false, now(), now(), now())",
        {
          employeeId: docs[0].drafterId,
          title: '자산 결재 결과: ' + status,
          summary: '결재 상태가 ' + status + '(으)로 반영되었습니다.',
          id,
        },
      );
      return { businessStatus };
    });
  }
}

