import { useState } from 'react';
import {
  call, Badge, DateText, Filters, Band, DataTable, Drawer, Pairs, Tiles, Form, Field,
  NumberInput, Select, LookupSelect, RefName, Num,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPES: [string, string][] = [
  ['구매품의', '구매품의'],
  ['검수조서', '검수조서'],
  ['대금지급', '대금지급'],
  ['실사계획', '실사계획'],
  ['자산변동', '자산변동'],
];
const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];
const TABLES: Record<string, string> = {
  구매품의: 'purchase_request',
  실사계획: 'asset_inspection_plan',
  자산변동: 'asset_change',
};
const PENDING = ['결재대기', '진행중', '보류'];

export default function FnSfr02507Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [open, setOpen] = useState<'submit' | 'result' | 'detail' | null>(null);
  const [sel, setSel] = useState<Row | null>(null);
  const [docType, setDocType] = useState('구매품의');
  const [docId, setDocId] = useState<number | string>('');
  const [resStatus, setResStatus] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [appliedStatus, setAppliedStatus] = useState('');

  const refreshAll = async (list: Row[]) => {
    const next = await Promise.all(
      list.map(async (r) => {
        const res = await call('GET', '/asset-approvals/' + String(r.approvalDocumentId), role);
        return { ...r, approvalStatus: res.approvalStatus, completedAt: res.completedAt };
      }),
    );
    setRows(next);
    return next;
  };

  const submit = async () => {
    if (docId === '' || docId === null) {
      throw new Error('상신할 문서 ID를 입력해 주세요.');
    }
    const res = await call('POST', '/asset-approvals', role, { documentType: docType, documentId: docId });
    const added: Row = { ...res, documentType: docType, documentId: docId };
    await refreshAll([added, ...rows]);
    notify('결재를 상신했습니다.');
    setDocId('');
    setOpen(null);
  };

  const applyResult = async () => {
    if (!sel || resStatus === '') {
      throw new Error('결재 상태를 선택해 주세요.');
    }
    await call('POST', '/asset-approvals/result', role, {
      approvalDocumentId: sel.approvalDocumentId,
      approvalStatus: resStatus,
    });
    await refreshAll(rows);
    notify('결재 결과를 반영했습니다.');
    setOpen(null);
  };

  const visible = appliedStatus === '' ? rows : rows.filter((r) => r.approvalStatus === appliedStatus);
  const waiting = rows.filter((r) => PENDING.includes(String(r.approvalStatus)));
  const done = rows.filter((r) => r.approvalStatus === '승인' || r.approvalStatus === '완료');

  const docCell = (r: Row) => {
    const table = TABLES[String(r.documentType)];
    return table ? <RefName table={table} role={role} value={r.documentId} /> : <Num value={r.documentId} />;
  };

  const columns = [
    { key: 'approvalDocumentId', label: '결재문서 ID' },
    { key: 'documentType', label: '문서 유형' },
    { key: 'documentId', label: '자산 업무 문서', render: docCell },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (r: Row) => <Badge value={r.approvalStatus} /> },
    { key: 'completedAt', label: '완료 일시', render: (r: Row) => <DateText value={r.completedAt} time /> },
    {
      key: 'action',
      label: '처리',
      render: (r: Row) =>
        PENDING.includes(String(r.approvalStatus)) ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              setSel(r);
              setResStatus('');
              setOpen('result');
            }}
          >
            결과 반영
          </button>
        ) : null,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>결재 현황</h2>
        <Tiles
          items={[
            ['상신 건수', rows.length],
            ['처리 대기', waiting.length],
            ['승인·완료', done.length],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>상신 내역</h2>
        <Filters
          onSearch={() => setAppliedStatus(filterStatus)}
          onReset={() => {
            setFilterStatus('');
            setAppliedStatus('');
          }}
        >
          <Field label="결재 진행 상태">
            <Select value={filterStatus} onChange={setFilterStatus} options={STATUSES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={visible.length}>
          <button
            type="button"
            onClick={() => {
              setDocType('구매품의');
              setDocId('');
              setOpen('submit');
            }}
          >
            결재 상신
          </button>
          <button type="button" onClick={() => void refreshAll(rows)}>
            상태 새로 읽기
          </button>
        </Band>
        <DataTable
          columns={columns}
          rows={visible}
          empty="이 화면에서 상신한 문서가 없습니다."
          onRowClick={(r) => {
            setSel(r);
            setOpen('detail');
          }}
        />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          columns={[
            { key: 'documentType', label: '문서 유형' },
            { key: 'approvalStatus', label: '상태', render: (r: Row) => <Badge value={r.approvalStatus} /> },
          ]}
          rows={waiting}
          empty="대기 중인 결재가 없습니다."
        />
      </section>
      {open === 'submit' && (
        <Drawer title="결재 상신" onClose={() => setOpen(null)}>
          <Form onSubmit={submit} submit="상신">
            <Field label="문서 유형" required hint="구매품의, 검수조서, 대금지급, 실사계획, 자산변동 중 선택">
              <Select
                value={docType}
                onChange={(v) => {
                  setDocType(v);
                  setDocId('');
                }}
                options={TYPES}
              />
            </Field>
            <Field label="상신할 자산 업무 문서" required>
              {TABLES[docType] ? (
                <LookupSelect table={TABLES[docType]} role={role} value={docId} onChange={setDocId} />
              ) : (
                <NumberInput value={docId} onChange={setDocId} />
              )}
            </Field>
          </Form>
        </Drawer>
      )}
      {open === 'result' && sel && (
        <Drawer title="결재 결과 반영" onClose={() => setOpen(null)}>
          <Form onSubmit={applyResult} submit="반영">
            <Field label="결재문서 ID">
              <Num value={sel.approvalDocumentId} />
            </Field>
            <Field label="결재 진행 상태" required>
              <Select value={resStatus} onChange={setResStatus} options={STATUSES} />
            </Field>
          </Form>
        </Drawer>
      )}
      {open === 'detail' && sel && (
        <Drawer title="결재 상태" onClose={() => setOpen(null)}>
          <Pairs
            items={[
              ['결재문서 ID', <Num value={sel.approvalDocumentId} />],
              ['문서 유형', String(sel.documentType)],
              ['자산 업무 문서', docCell(sel)],
              ['결재 진행 상태', <Badge value={sel.approvalStatus} />],
              ['완료 일시', <DateText value={sel.completedAt} time />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
